    store: ActionConversationStore
    usageValuesService?: ActionUsageValuesService
}

/** Conversation surface; owns selection, live-run, visibility, and acknowledgement subscriptions. */
export function ActionConversationChat(
    { actionId, bindingStore, context, popupEntryId, searchService, store, usageValuesService }: ActionConversationChatProps,
) {
    const selectAcknowledgementConversation = useMemo(() => createAcknowledgementConversationSelector(), [])
    const commands = useMemo(
        () => new ActionConversationCommandService(actionId, context, store),
        [actionId, context, store],
    )
    const boundRunId = useBoundRunId(bindingStore)
    const liveConversation = useRunSelector(boundRunId, selectAcknowledgementConversation)
    const { selectedConversation } = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const popupEntries = useSyncExternalStore(
        subscribeCardPopups,
        () => cardPopupService.getSnapshot(),
        () => cardPopupService.getSnapshot(),
    )
    const conversation = resolveDisplayedConversation(liveConversation, selectedConversation)
    const scope = context.cardInternalId ?? null
    const popupVisible = popupEntries.at(-1)?.id === popupEntryId
    const visible = !!popupEntryId && popupVisible && !!conversation

    useEffect(() => {
        if (!popupEntryId || !conversation) return undefined

        agentAcknowledgementService.setConversationVisible(popupEntryId, scope, actionId, conversation, visible)

        return () => agentAcknowledgementService.setConversationVisible(
            popupEntryId, scope, actionId, conversation, false,
        )
    }, [actionId, conversation, popupEntryId, scope, visible])

    return (
        <Stack spacing={1} sx={{ flex: 1, minHeight: 0 }}>
            <ActionConversationTranscript
                bindingStore={bindingStore}
                commands={commands}
                searchService={searchService}
                store={store}
            />
            <ConversationMetaInfo bindingStore={bindingStore} store={store} usageValuesService={usageValuesService} />
        </Stack>
    )
}

        this.navigationToken += 1
        this.processedRunIds.clear()
        this.pendingCopyRecordsBySourceId.clear()
        this.projectKey = null
        this.unsubscribeRunEvents?.()
        this.unsubscribeRunEvents = null
        this.setLegendCollapsed(false)
        this.setLegendPosition(null)
        this.setCurrentSelection(null)
        this.setMenu(null)
        this.setPopup(null)
        this.setRootMenu(null)
        this.applySnapshot(initialSnapshot(), null)
    }

    /** Loads the index on first activation; a failed load is retried by the next call. */
    async open() {
        if (!this.binding) throw new Error('Diagram view is not bound to a project')
        this.unsubscribeRunEvents ??= this.dependencies.subscribeRunEvents(this.handleRunEvent)
        this.loadPromise ??= this.load()
        await this.loadPromise
    }

    openRootPopup(anchorElement: HTMLElement) {
        this.requireReady()
        if (this.snapshot.popup?.context.type === 'root') {
            this.closePopup()

            return
        }
        this.setMenu(null)
        this.setRootMenu(null)
        this.setPopup({ anchorElement, context: diagramContext('root') })
    }

    openRootMenu(anchorElement: HTMLElement) {
        this.requireReady()
        this.setMenu(null)
        this.setPopup(null)
        this.setRootMenu({ anchorElement })
    }

    closeRootMenu() {
        this.setRootMenu(null)
    }

    openNewRootPopup(anchorElement: HTMLElement) {
        this.requireReady()
        const context = diagramContext('root')
        const rootActions = actionsForContext(this.dependencies.loadActions(), context)
        if (rootActions.length === 0) throw new Error('Cannot open a root diagram action without a configured root action')
        const initialActionId = rootActions.find(({ id }) => (this.snapshot.index.roots[id]?.length ?? 0) === 0)?.id
        this.setRootMenu(null)
        this.setPopup({ anchorElement, context, ...(initialActionId ? { initialActionId } : {}) })
    }

    openChildPopup(actionId: string) {
        this.requireReady()
        const menu = this.snapshot.menu
        if (!menu) throw new Error('Cannot open a child diagram action without a selected item')
        const context = diagramContext('child', menu.diagramId, menu.itemId, menu.itemLabel)
        this.setMenu(null)
        this.setPopup({ anchorElement: menu.anchorElement, context, initialActionId: actionId })
    }

    openSelectedItemPopup(anchorElement: HTMLElement) {
        this.requireReady()
        const selection = this.currentSelection
        if (!selection) throw new Error('Cannot open a child diagram action without a selected Current item')
        const activeDiagramId = this.snapshot.index.activePath.at(-1)
        if (selection.activeDiagramId !== activeDiagramId) {
            throw new Error('Cannot open a child diagram action for a stale Current selection')
        }
        const context = diagramContext('child', selection.activeDiagramId, selection.itemId, selection.itemLabel)
        this.setMenu(null)
        this.setRootMenu(null)
        this.setPopup({ anchorElement, context })
    }

    closePopup() {
        this.setPopup(null)
    }

    collapseLegend() {
        this.setLegendCollapsed(true)
    }

    expandLegend() {
        this.setLegendCollapsed(false)
    }
